create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null default 'Player', age_confirmed boolean not null default false, created_at timestamptz not null default now());
create function public.new_profile() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'display_name','Player')); return new; end; $$;
create trigger on_signup after insert on auth.users for each row execute function public.new_profile();
create table public.games (id text primary key, owner_id uuid references profiles(id) on delete cascade, title text not null, description text not null, orientation text not null check(orientation in ('portrait','landscape')), current_version_id text, is_public boolean not null default false, fixture boolean not null default false, deleted_at timestamptz, created_at timestamptz not null default now());
create table public.game_versions (id text primary key, game_id text not null references games(id) on delete cascade, number integer not null, artifact_key text not null unique, source_key text not null unique, package_bytes integer not null, checksum text not null, state_schema_version integer not null default 1, created_at timestamptz not null default now(), unique(game_id,number), unique(id,game_id));
alter table games add constraint current_version_fk foreign key(current_version_id) references game_versions(id) deferrable initially deferred;
create table public.share_invitations (id text primary key, game_id text not null references games(id) on delete cascade, owner_id uuid not null references profiles(id) on delete cascade, token_hash text not null unique, expires_at timestamptz not null, revoked boolean not null default false, created_at timestamptz not null default now());
create table public.game_members (game_id text not null references games(id) on delete cascade, user_id uuid not null references profiles(id) on delete cascade, invitation_id text references share_invitations(id) on delete cascade, created_at timestamptz not null default now(), primary key(game_id,user_id));
create table public.blocked_users (user_id uuid not null references profiles(id) on delete cascade, creator_id uuid not null references profiles(id) on delete cascade, primary key(user_id,creator_id));
create table public.hidden_games (user_id uuid not null references profiles(id) on delete cascade, game_id text not null references games(id) on delete cascade, primary key(user_id,game_id));
create table public.generation_jobs (id text primary key, game_id text not null references games(id) on delete cascade, user_id uuid not null references profiles(id) on delete cascade, prompt text not null, kind text not null check(kind in ('create','modify')), stage text not null default 'queued', error text, base_version_id text references game_versions(id), reserved_cost numeric(12,6) not null default 0, charged_cost numeric(12,6) not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index generation_user_day on generation_jobs(user_id,created_at);
create table public.generation_events (id bigint generated always as identity primary key, generation_id text references generation_jobs(id) on delete cascade, stage text not null, created_at timestamptz not null default now());
create table public.generation_outbox (generation_id text primary key references generation_jobs(id) on delete cascade, dispatched_at timestamptz);
create table public.player_saves (user_id uuid not null references profiles(id) on delete cascade, game_id text not null references games(id) on delete cascade, version_id text not null, schema_version integer not null, revision integer not null default 1, state jsonb not null check(octet_length(state::text)<=65536), updated_at timestamptz not null default now(), primary key(user_id,game_id), foreign key(version_id,game_id) references game_versions(id,game_id));
create table public.game_scores (user_id uuid not null references profiles(id) on delete cascade, game_id text not null references games(id) on delete cascade, version_id text not null, score bigint not null check(score>=0 and score<=1000000000), updated_at timestamptz not null default now(), primary key(user_id,game_id), foreign key(version_id,game_id) references game_versions(id,game_id));
create table public.game_reports (id bigint generated always as identity primary key, game_id text references games(id) on delete cascade, reporter_id uuid not null references profiles(id) on delete cascade, reason text not null, detail text not null, status text not null default 'open', created_at timestamptz not null default now());
create table public.inference_usage (id bigint generated always as identity primary key, generation_id text references generation_jobs(id) on delete cascade, model text not null, estimated_cost numeric(12,6) not null, actual_cost numeric(12,6), prompt_tokens integer, completion_tokens integer, created_at timestamptz not null default now());

create function public.can_play(gid text) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from games g where g.id=gid and g.deleted_at is null and (g.is_public or g.owner_id=auth.uid() or exists(select 1 from game_members m join share_invitations s on m.invitation_id=s.id where m.game_id=g.id and m.user_id=auth.uid() and not s.revoked)) and not exists(select 1 from blocked_users b where b.user_id=auth.uid() and b.creator_id=g.owner_id)); $$;
create function public.owns_game(gid text) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from games where id=gid and owner_id=auth.uid() and deleted_at is null); $$;
revoke all on function public.can_play(text),public.owns_game(text) from public;
grant execute on function public.can_play(text),public.owns_game(text) to authenticated;
alter table profiles enable row level security;
create policy profile_self on profiles for all to authenticated using(id=auth.uid()) with check(id=auth.uid());
alter table games enable row level security;
create policy game_read on games for select to authenticated using(can_play(id));
create policy game_owner on games for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
alter table game_versions enable row level security;
create policy version_read on game_versions for select to authenticated using(can_play(game_id));
alter table share_invitations enable row level security;
create policy share_owner on share_invitations for select to authenticated using(owner_id=auth.uid());
alter table game_members enable row level security;
create policy member_read on game_members for select to authenticated using(user_id=auth.uid() or owns_game(game_id));
alter table player_saves enable row level security;
create policy save_self on player_saves for all to authenticated using(user_id=auth.uid() and can_play(game_id)) with check(user_id=auth.uid() and can_play(game_id));
alter table game_scores enable row level security;
create policy score_read on game_scores for select to authenticated using(can_play(game_id));
create policy score_self on game_scores for all to authenticated using(user_id=auth.uid() and can_play(game_id)) with check(user_id=auth.uid() and can_play(game_id));
alter table generation_jobs enable row level security;
create policy generation_self on generation_jobs for select to authenticated using(user_id=auth.uid());
alter table generation_events enable row level security;
create policy event_self on generation_events for select to authenticated using(exists(select 1 from generation_jobs where id=generation_id and user_id=auth.uid()));
alter table game_reports enable row level security;
create policy report_self on game_reports for select to authenticated using(reporter_id=auth.uid());
alter table blocked_users enable row level security;
create policy block_self on blocked_users for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
alter table hidden_games enable row level security;
create policy hidden_self on hidden_games for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
alter table generation_outbox enable row level security;
alter table inference_usage enable row level security;
-- Backend owns writes that require quotas/authorization. Direct Supabase clients may only read.
revoke insert,update,delete on games,game_versions,share_invitations,game_members,generation_jobs,generation_events,generation_outbox,inference_usage,player_saves,game_scores,game_reports from authenticated,anon;
grant select on games,game_versions,player_saves,game_scores,generation_jobs,generation_events,share_invitations,game_members to authenticated;
